ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'docs/diocese-catalog'; IMG=OUT/'images'
VIS=IMG/'visual-report';VIS.mkdir(exist_ok=True)
DATA=json.loads((OUT/'research/inventory.json').read_text(encoding='utf-8'))
MOBILE=json.loads((OUT/'research/mobile.json').read_text(encoding='utf-8'))
FONT='C:/Windows/Fonts/arial.ttf'; BOLD='C:/Windows/Fonts/arialbd.ttf'
INK='#20374A';GOLD='#A87927';RED='#B24E42';GREEN='#39766E';GREY='#E4E8EA'

def font(size=30,bold=False):return ImageFont.truetype(BOLD if bold else FONT,size)
def wrap(draw,text,width,size=28,bold=False):
    lines=[];line=''
    for word in text.split():
        test=(line+' '+word).strip()
        if draw.textlength(test,font=font(size,bold))>width and line:lines.append(line);line=word
        else:line=test
    if line:lines.append(line)
    return '\n'.join(lines)

def gallery(name,items,height=840):
    canvas=Image.new('RGB',(1800,height),'white');dr=ImageDraw.Draw(canvas)
    cell=1800//len(items)
    for i,(path,title,note) in enumerate(items):
        x=i*cell+12
        dr.multiline_text((x,5),wrap(dr,title,cell-28,30,True),font=font(30,True),fill=INK,spacing=4)
        im=Image.open(path).convert('RGB')
        thumb=ImageOps.contain(im,(cell-34,height-165))
        canvas.paste(thumb,(x+(cell-28-thumb.width)//2,88))
        dr.multiline_text((x,height-65),wrap(dr,note,cell-28,22),font=font(22),fill=INK,spacing=3)
    target=VIS/(name+'.png');canvas.save(target);return target

def bars(name,rows):
    canvas=Image.new('RGB',(1800,700),'white');dr=ImageDraw.Draw(canvas)
    for i,(title,a,b,left,right) in enumerate(rows):
        y=25+i*220;dr.text((30,y),title,font=font(34,True),fill=INK)
        total=a+b;length=1700;cut=int(length*a/total)
        dr.rectangle((30,y+66,30+cut,y+126),fill=GREEN)
        dr.rectangle((30+cut,y+66,30+length,y+126),fill=GOLD)
        dr.text((30,y+143),f'{a} из {total}  ·  {a/total:.1%}  {left}'.replace('.',','),font=font(28),fill=GREEN)
        dr.text((930,y+143),f'{b} из {total}  ·  {b/total:.1%}  {right}'.replace('.',','),font=font(28),fill=GOLD)
    target=VIS/(name+'.png');canvas.save(target);return target

def errors():
    im=Image.new('RGB',(1800,680),'white');dr=ImageDraw.Draw(im)
    for i,(number,title,text) in enumerate([(3,'Имя сайта не найдено','Пфорцхайм · Вупперталь · община Кирилла и Мефодия в Гамбурге'),(1,'Ошибка сертификата','Зулинген · имя в сертификате не совпадает с адресом'),(1,'Требуется авторизация','Бад Кройцнах · HTTP 401')]):
        x=i*600+25;dr.text((x,20),str(number),font=font(150,True),fill=RED)
        dr.multiline_text((x,210),wrap(dr,title,550,34,True),font=font(34,True),fill=INK,spacing=8)
        dr.multiline_text((x,335),wrap(dr,text,540,30),font=font(30),fill=INK,spacing=10)
        dr.text((x,590),'Подтверждено повторным запросом',font=font(23),fill=RED)
    p=VIS/'errors.png';im.save(p);return p

def document():
    d=Document();s=d.sections[0];s.orientation=WD_ORIENT.LANDSCAPE
    s.page_width=Inches(11);s.page_height=Inches(8.5)
    s.top_margin=Inches(.58);s.bottom_margin=Inches(.55);s.left_margin=s.right_margin=Inches(.65)
    for name,size in [('Normal',11),('Title',25),('Subtitle',13),('Heading 1',21),('Heading 2',14),('Caption',9)]:
        st=d.styles[name];st.font.name='Arial';st.font.size=Pt(size);st.font.color.rgb=RGBColor(0,0,0)
        st.font.bold=name.startswith('Heading');st.paragraph_format.space_after=Pt(7)
        for b in st.element.xpath('.//w:pBdr'):b.getparent().remove(b)
    d.styles['Normal'].paragraph_format.line_spacing=1.06
    s.header.paragraphs[0].text='ПРИХОД  |  Материалы для Владыки Тихона  |  15 октября 2026'
    s.header.paragraphs[0].style='Caption'
    p=s.footer.paragraphs[0];p.alignment=2;p.add_run('Приход  ·  ')
    f=OxmlElement('w:fldSimple');f.set(qn('w:instr'),'PAGE');p._p.append(f)
    d.core_properties.author='Проект Приход';return d

def page(d,title,text='',image=None,caption='',first=False):
    if not first:d.add_page_break()
    d.add_heading(title,0 if first else 1)
    if text:d.add_paragraph(text)
    if image:
        im=Image.open(image);w,h=im.size;display=min(9.6,4.6*w/h)
        p=d.add_paragraph();p.alignment=1;p.add_run().add_picture(str(image),width=Inches(display))
    if caption:d.add_paragraph(caption,style='Caption')

def shot(n):return IMG/f'mobile-{n:02}.png'
def g(name,items):return gallery(name,items)
def summary(d):
    page(d,'Обзор сайтов епархии',
         'Проверены все 102 карточки из официального списка. Адреса относятся к 68 доменам; один сайт может обслуживать несколько общин.',
         bars('summary',[('Есть ли ссылка в карточке прихода',76,26,'ссылка есть','ссылка не указана'),('Открывается ли опубликованный адрес',65,5,'получен HTML','повторная ошибка'),('Помещается ли страница в экран 390 px',45,20,'нет превышения ширины','ширина превышена')]),
         'Срез 15.10.2026 · rokmp.de/churches-by-cities/ · 70 адресов, включая варианты и общие сайты. HTML ответ и отсутствие превышения ширины не гарантируют полноценную работу сайта.',first=True)

def overview():
    d=document();summary(d)
    deleted=VIS/'deleted-fragment.png'
    Image.open(shot(45)).crop((0,0,375,110)).save(deleted)
    page(d,'Доступность и содержание нужно оценивать раздельно','Пять адресов дали повторную ошибку. Ещё один адрес отвечает, но показывает сообщение об удалении сайта. Это разные состояния.',errors(),'Источник: сохранённые повторные запросы. Сетевая ошибка из точки проверки не доказывает, что приход прекратил работу или сайт никогда не создавался.')
    page(d,'Адрес открывается но сайт удалён','Указанный для Саарбрюккена адрес отображает сообщение «This site was deleted». Та же ссылка дана общине Кайзерслаутерна. Нужен актуальный адрес, подтверждённый общиной.',g('deleted',[(deleted,'Саарбрюккен','Увеличенный фрагмент сообщения'),(shot(64),'Бад Липпшпринге','Старый сайт сообщает о переезде')]),'Слева: фрагмент saarbruecken.orthodoxy.ru. Справа: rokmp-bielefeld.de → russisch-orthodoxe-kirche-paderborn.de. Переезд на новый сайт не является отсутствием сайта.')
    page(d,'Устаревшее расписание и актуальные даты','Тюбинген: в разделе ближайших богослужений стоят даты 16–30 августа 2025 года. Нюрнберг: опубликованы службы октября и ноября 2026 года. Актуальность сведений и качество вёрстки оцениваются отдельно.',g('dates',[(shot(32),'Тюбинген','Ближайшие службы остались в 2025 году'),(shot(15),'Нюрнберг','Даты актуальны но строки обрезаются')]),'Источники: orthodoxekirche.de/Tuebingen/ и rus-kirche.de. Вывод относится к проверенным страницам; наличие другого актуального ресурса Тюбингена не установлено.')
    page(d,'Рамки затрудняют навигацию на телефоне','На экране 390 px шапка, узкое меню и содержимое оказываются в независимых областях прокрутки. Обычный замер общей ширины страницы эту проблему не выявляет.',g('frames',[(shot(21),'Бранденбург','Узкая область меню и отдельные прокрутки'),(shot(8),'Шпандау','Та же рамочная модель страницы'),(IMG/'project-schedule-fragment.png','Приход','Карточки расписания без рамок')]),'Существующие сайты: brandenburg.orthodox.bplaced.de/ru/index.html и orthodox-spandau.bplaced.net/ru/. Справа — фрагмент проверенного демонстрационного продукта, а не выполненный переезд этих общин.')
    page(d,'Широкая вёрстка обрезает полезную информацию','В 20 из 65 мобильных просмотров ширина документа превысила экран более чем на 2 px. Ниже показаны три конкретных случая. Доли относятся к адресам, а не к числу приходов.',g('wide',[(shot(9),'Констанц','Документ 768 px при экране 390 px'),(shot(27),'Кобленц','Документ 1024 px при экране 390 px'),(shot(34),'Дюссельдорф','Документ 981 px при экране 390 px')]),'Снимки первого визита 15.10.2026. Превышение ширины — технический признак; причины и отдельные прокручиваемые блоки требуют рассмотрения в контексте страницы.')
    page(d,'Размер заголовка влияет на поиск расписания','В Бремене длинный заголовок выходит за экран. В Вормсе заголовок занимает большую часть первого экрана. Посетителю приходится прокручивать или искать меню прежде чем добраться до практической информации.',g('headings',[(shot(6),'Бремен','Заголовок обрезается справа'),(shot(11),'Вормс','Заголовок занимает первый экран'),(shot(2),'Франкфурт','Ближайшая служба видна сразу')]),'Источники: orthodox-bremen.cerkov.ru, prihod-worms.cerkov.ru, frankfurt.orthodoxy.ru → orthodoxekirche.org. Пример Франкфурта показывает удачное существующее решение.')
    page(d,'Расписание изображением требует увеличения','На первом экране мюнхенского сайта расписание представлено изображением с мелким текстом. В структурированном расписании «Прихода» время и название службы остаются отдельными элементами карточки.',g('schedule-comparison',[(shot(18),'Мюнхен','Лист расписания в виде изображения'),(IMG/'project-schedule-fragment.png','Приход','Структурированные карточки служб')]),'Слева: voskresenie.de. Справа: фрагмент живой проверки Core rc.20 от 14.10.2026. Содержание и фактическое расписание в обоих случаях определяет приход.')
    page(d,'Удачные сайты дают ориентиры для остальных','Уже существуют полезные решения: ближайшее богослужение на первом экране, немецкоязычное приглашение, понятные разделы контактов и расписания. Их стоит сохранять и использовать как ориентиры.',g('good',[(shot(2),'Франкфурт','Ближайшее богослужение сразу'),(shot(52),'Гёттинген','Немецкий язык и раздел Gottesdienste'),(shot(61),'Берлинский собор','Языки расписание и способы связи')]),'Источники: orthodoxekirche.org, orthodoxia-goettingen.de, soborberlin.com. Скриншоты показывают первые экраны; перечисленные разделы также проверены в содержимом страниц. Замена работающего сайта не является самоцелью.')
    page(d,'Что приход сможет делать самостоятельно','«Приход» даёт готовую структуру: сотрудник заполняет сведения, выбирает оформление, ведёт службы и принимает обращения. Мы готовы помочь с техническим запуском и обучением; повседневные изменения выполняет приход.',g('product-answer',[(IMG/'project-schedule-fragment.png','Изменять расписание','Переносы отмены и несколько мест служения'),(IMG/'project-question-fragment.png','Принимать обращения','Форма без регистрации посетителя')]),'Проверенные интерфейсы проекта. Простоту освоения необходимо измерить в пилоте; время запуска и экономия пока не установлены. WordPress и техническое обслуживание требуют ответственного.')
    for start in range(0,len(MOBILE),4):
        group=MOBILE[start:start+4]
